def unit_of_work(metadata=None, timeout=None):
    """Decorator to run a function within a Neo4j transaction with optional metadata and timeout."""
    def decorator(func):
        def wrapper(session, *args, **kwargs):
            if timeout is not None:
                if timeout < 0:
                    raise ValueError("timeout must be non-negative or None")
            with session.begin_transaction(timeout=timeout, metadata=metadata) as tx:
                return func(tx, *args, **kwargs)
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    if not hasattr(self, "_data"):
        raise AttributeError("Missing '_data' attribute")
    try:
        return self._data.index(key)
    except ValueError:
        raise ValueError(f"{key} not found in the data")

def values(self, *keys):
        """
        Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # Determine the underlying data structure
        # Prefer a private _data attribute if present, otherwise fall back to dict-like interface
        if hasattr(self, "_data"):
            data = self._data
        else:
            # Assume the object behaves like a mapping
            data = self

        # If no keys are specified, return all values
        if not keys:
            # Preserve order if possible
            if isinstance(data, dict):
                return list(data.values())
            else:
                # Fallback: iterate over items
                return [v for _, v in data.items()]

        # Build a list of all values in order for index-based access
        if isinstance(data, dict):
            items = list(data.items())
        else:
            items = list(data.items())
        all_values = [v for _, v in items]

        result = []
        for key in keys:
            if isinstance(key, int):
                # Index-based access
                result.append(all_values[key])
            else:
                # Key-based access
                result.append(data[key])
        return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    # Set defaults
    mode = mode or "WRITE"
    bookmarks = list(bookmarks) if bookmarks is not None else []
    metadata = metadata or {}
    # Store hooks for later use
    self._dehydration_hooks = dehydration_hooks or {}
    self._hydration_hooks = hydration_hooks or {}
    # Construct the BEGIN message payload
    payload = [mode, bookmarks, metadata, timeout, db, imp_user]
    # Append the message to the output queue (0x01 is the BEGIN opcode)
    self._output_queue.append((0x01, *payload))
    # Return a Response object that will handle the server reply
    return Response(self, **handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Prepare attributes dictionary for the new class
    attrs = {}
    # If fields is a dict, use its keys as attribute names; otherwise assume an iterable of names
    if isinstance(fields, dict):
        for field in fields:
            attrs[field] = None
    else:
        for field in fields:
            attrs[field] = None

    # Define an __init__ that accepts x, y and optional keyword arguments for the custom fields
    def __init__(self, x, y, **kwargs):
        super(self.__class__, self).__init__(x, y)
        for key, value in kwargs.items():
            if key in attrs:
                setattr(self, key, value)
            else:
                raise TypeError(f"Unexpected keyword argument: {key}")

    attrs['__init__'] = __init__

    # Attach SRID if provided in the mapping
    if srid_map and name in srid_map:
        attrs['srid'] = srid_map[name]

    # Create and return the new subclass of Point
    return type(name, (Point,), attrs)

def deprecated(message):
    def decorator(func):
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

