def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dictionary is empty')
    key = next(iter(self))
    return key, self.pop(key)

def get(self, key, default=None):
        """
        D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
        """
        try:
            return self[key]
        except KeyError:
            return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if k in cache:
                return cache[k]
            result = func(*args, **kwargs)
            if lock:
                with lock:
                    cache[k] = result
            else:
                cache[k] = result
            return result
        return wrapper
    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback, os
    def _format_exc(exc):
        lines = []
        tb = exc.__traceback__
        stack = traceback.extract_tb(tb)
        # keep only the last max_level frames
        stack = stack[-max_level:]
        for frame in stack:
            # shorten file path
            path = frame.filename
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                path = os.sep.join(['...'] + parts[-max_path_level:])
            lines.append(f'  File "{path}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f'    {frame.line.strip()}')
        exc_type = type(exc).__name__
        exc_msg = str(exc)
        lines.append(f'{exc_type}: {exc_msg}')
        return '\n'.join(lines)
    parts = []
    current = e
    while current:
        parts.append(_format_exc(current))
        if current.__cause__:
            parts.append('The above exception was the direct cause of the following exception:')
            current = current.__cause__
        elif current.__context__ and not current.__suppress_context__:
            parts.append('During handling of the above exception, another exception occurred:')
            current = current.__context__
        else:
            break
    return '\n\n'.join(parts)

