def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # If _err_indices is a dict mapping coordinate names to indices
    err_indices = getattr(self, "_err_indices", None)
    if isinstance(err_indices, dict):
        try:
            return err_indices[coord_name]
        except KeyError:
            raise KeyError(f"Coordinate {coord_name!r} not found in error indices.")
    # If _err_indices is a list/tuple/array of indices
    if isinstance(err_indices, (list, tuple, np.ndarray)):
        # Find the coordinate's position in the coordinate list
        coords = getattr(self, "_coords", None)
        if coords is None:
            raise AttributeError("Attribute _coords not found.")
        try:
            idx = coords.index(coord_name)
        except ValueError:
            raise ValueError(f"Coordinate {coord_name!r} not found in coordinates.")
        # Return the corresponding error index
        return err_indices[idx]
    # If _err_indices is not set or unsupported type
    raise AttributeError("Attribute _err_indices not found or unsupported type.")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences
    if isinstance(seq, Source):
        return False
    # Single FillRequest instance
    if isinstance(seq, FillRequest):
        return True
    # Avoid treating strings or bytes as sequences
    if isinstance(seq, (str, bytes)):
        return False
    # Try to iterate over seq
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    # Check for at least one FillRequest element
    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return (
        hasattr(obj, 'fill') and callable(getattr(obj, 'fill')) and
        hasattr(obj, 'request') and callable(getattr(obj, 'request'))
    )

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))

def _validate_labels(labels):
    import re
    from collections.abc import Mapping, Iterable

    # Regular expressions for label keys and values (simplified)
    LABEL_KEY_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')
    LABEL_VALUE_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')

    errors = []

    if not isinstance(labels, Mapping):
        raise ValidationError([{'labels': 'labels must be a mapping'}])

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not LABEL_KEY_REGEX.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{LABEL_KEY_REGEX.pattern}]"})

        # Validate value
        # If value is a list or tuple, validate each element
        if isinstance(value, (list, tuple)):
            for elem in value:
                if not isinstance(elem, str):
                    errors.append({repr(elem): 'expected string or bytes-like object'})
                else:
                    if not LABEL_VALUE_REGEX.match(elem):
                        errors.append({elem: f"Label value '{elem}' does not match the regex [{LABEL_VALUE_REGEX.pattern}]"})
        else:
            if not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not LABEL_VALUE_REGEX.match(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [{LABEL_VALUE_REGEX.pattern}]"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes manifest dictionary.
    Non-dict and non-list values are replaced with None, except for identifying fields at the top level.
    Identifying fields (apiVersion, kind, metadata) are copied from the manifest when first_level is True.
    """
    def _process_list(lst):
        new_list = []
        for item in lst:
            if isinstance(item, dict):
                new_list.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                new_list.append(_process_list(item))
            else:
                new_list.append(None)
        return new_list

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            if first_level and key in ("apiVersion", "kind", "metadata"):
                # Copy the entire dict for identifying fields at the top level
                result[key] = value
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = _process_list(value)
        else:
            if first_level and key in ("apiVersion", "kind", "metadata"):
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Existing custom observer schemas, if any
    existing_schemas = getattr(app.spec, "observer_schema", {})
    default_schemas = {}

    # Iterate over all resources in the application's manifest
    for resource in app.spec.manifest:
        kind = resource.get("kind")
        if not kind:
            continue  # Skip resources without a kind

        # Skip if a custom schema is already defined for this kind
        if kind in existing_schemas:
            continue

        # Create a minimal default schema that observes the resource's metadata
        default_schemas[kind] = {
            "metadata": {
                "name": "",
                "namespace": "",
                "labels": {},
                "annotations": {},
            }
        }

    return default_schemas

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    # Helper to validate a single object directory
    def _validate_object_dir(obj_path):
        # Must be a directory
        if not os.path.isdir(obj_path):
            return False
        # Must contain a .ocfl_version file
        ocfl_version_file = os.path.join(obj_path, ".ocfl_version")
        if not os.path.isfile(ocfl_version_file):
            return False
        # Must contain an 'objects' directory
        objects_dir = os.path.join(obj_path, "objects")
        if not os.path.isdir(objects_dir):
            return False
        # Basic sanity: objects dir should contain at least one subdirectory
        try:
            subdirs = [d for d in os.listdir(objects_dir)
                       if os.path.isdir(os.path.join(objects_dir, d))]
        except Exception:
            return False
        if not subdirs:
            return False
        return True

    # If path is a pyfilesystem root (has listdir and opendir)
    if hasattr(path, "listdir") and hasattr(path, "opendir"):
        # Iterate over all entries in the root
        for entry in path.listdir():
            try:
                sub = path.opendir(entry)
            except Exception:
                continue
            # Validate each subdirectory as an OCFL object
            if not self.validate(sub):
                return False
        return True

    # Otherwise treat path as a filesystem path string
    if isinstance(path, str):
        # If path is a directory, validate it as an OCFL object
        if os.path.isdir(path):
            return _validate_object_dir(path)
        # If path is a file, it might be a pyfs root path string; try to open it
        try:
            import pyfilesystem2 as fs
            root = fs.open_fs(path)
            return self.validate(root)
        except Exception:
            return False

    # Unsupported type
    return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix + 'unknown'
    if hasattr(status, 'name'):
        status_str = status.name
    else:
        status_str = str(status)
    return f"{prefix}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # If the validation log attribute does not exist or is empty, return an empty string
    if not hasattr(self, 'validation_log') or not self.validation_log:
        return ''
    # Prefix each log entry and join them with newlines
    return "\n".join(f"{prefix}{msg}" for msg in self.validation_log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    # Determine spec_version
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        type_to_spec = {
            'inventory': '1.0',
            'inventory_v2': '2.0',
            'inventory_v3': '3.0',
        }
        if type_val in type_to_spec:
            spec_version = type_to_spec[type_val]
    # Validate spec_version
    allowed_versions = {'1.0', '2.0', '3.0'}
    if spec_version not in allowed_versions:
        raise ValueError(f"Unsupported spec_version: {spec_version}")
    # Validate required top-level keys
    required_keys = ['name', 'description', 'components']
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key: {key}")
    # Validate components
    components = inventory['components']
    if not isinstance(components, list):
        raise ValueError("components must be a list.")
    for idx, comp in enumerate(components):
        if not isinstance(comp, dict):
            raise ValueError(f"Component at index {idx} must be a dict.")
        comp_required = ['name', 'type', 'properties']
        for ck in comp_required:
            if ck not in comp:
                raise ValueError(f"Component at index {idx} missing required key: {ck}")
        if not isinstance(comp['properties'], dict):
            raise ValueError(f"Component at index {idx} properties must be a dict.")
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Get the state for the requested version
    state = inventory.get(version)
    if state is None:
        return {}

    # Prepare a sorted list of all versions to iterate over later ones
    try:
        sorted_versions = sorted(inventory.keys())
    except TypeError:
        # If keys are not directly comparable, fall back to list order
        sorted_versions = list(inventory.keys())

    result = {}
    for logical_path, content_file in state.items():
        files_set = {content_file}
        for later_version in sorted_versions:
            if later_version <= version:
                continue
            later_state = inventory.get(later_version)
            if later_state and logical_path in later_state:
                files_set.add(later_state[logical_path])
        result[logical_path] = files_set

    return result

def files_list(path):
    """Return the files in `path`"""
    return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]

