def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary where each key is the basename of an XML file (without extension)
        and each value is a dictionary containing:
            - 'xml': the decoded XML content (or None if not present)
            - 'files': a list of other file names in the zip that share the same basename
    """
    import zipfile
    import os

    packages = {}
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for entry in zf.namelist():
            # Skip directories
            if entry.endswith('/'):
                continue
            base, ext = os.path.splitext(os.path.basename(entry))
            if base not in packages:
                packages[base] = {'xml': None, 'files': []}
            if ext.lower() == '.xml':
                try:
                    content = zf.read(entry)
                    # Try to decode as UTF-8, fallback to latin1 if needed
                    try:
                        packages[base]['xml'] = content.decode('utf-8')
                    except UnicodeDecodeError:
                        packages[base]['xml'] = content.decode('latin1')
                except Exception:
                    packages[base]['xml'] = None
            else:
                packages[base]['files'].append(entry)
    return packages

def fix_namespace_prefix_w(content):
    """
