def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    import pprint
    try:
        data = self.__dict__
    except AttributeError:
        return str(self)
    if debug:
        header = f"{self.__class__.__name__} (id={id(self)})"
        return f"{header}\n{pprint.pformat(data, indent=indent)}"
    return pprint.pformat(data, indent=indent)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    @functools.wraps(namefunc)
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            try:
                unicode_type = unicode
            except NameError:
                unicode_type = str
            if isinstance(result, unicode_type):
                return result.encode('utf-8')
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import importlib.metadata as metadata
    except ImportError:
        try:
            from importlib_metadata import metadata
        except ImportError:
            return "0.0.0"
    pkg = __package__ or __name__
    try:
        return metadata.version(pkg)
    except Exception:
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Extract pieces from dict or sequence
    if isinstance(pieces, dict):
        major = pieces.get('major')
        minor = pieces.get('minor')
        patch = pieces.get('patch')
        pre = pieces.get('pre_release')
        build = pieces.get('build')
    else:
        major = pieces[0] if len(pieces) > 0 else None
        minor = pieces[1] if len(pieces) > 1 else None
        patch = pieces[2] if len(pieces) > 2 else None
        pre = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None

    # Helper to convert to string, defaulting to '0' for missing numeric parts
    def to_str(val, default='0'):
        if val is None:
            return default
        return str(val)

    major_s = to_str(major)
    minor_s = to_str(minor)
    patch_s = to_str(patch)
    pre_s = to_str(pre, default='')
    build_s = to_str(build, default='')

    style = style.lower() if isinstance(style, str) else 'semver'

    if style == 'semver':
        base = f"{major_s}.{minor_s}.{patch_s}"
        if pre_s:
            base += f"-{pre_s}"
        if build_s:
            base += f"+{build_s}"
        return base

    if style == 'pep440':
        base = f"{major_s}.{minor_s}.{patch_s}"
        if pre_s:
            # Simplified handling: rc for release candidate, dev otherwise
            if pre_s.lower().startswith('rc'):
                base += f"rc{pre_s[2:]}"
            else:
                base += f"dev{pre_s}"
        if build_s:
            base += f".post{build_s}"
        return base

    if style == 'git':
        base = f"{major_s}.{minor_s}.{patch_s}"
        if pre_s:
            base += f"-{pre_s}"
        return base

    if style == 'full':
        parts = [major_s, minor_s, patch_s]
        if pre_s:
            parts.append(pre_s)
        if build_s:
            parts.append(build_s)
        return '.'.join(parts)

    # Default to semver if style is unrecognized
    return f"{major_s}.{minor_s}.{patch_s}{('-' + pre_s) if pre_s else ''}{('+' + build_s) if build_s else ''}"

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '.' if any(p == '+' for p in pieces) else '+'

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Attach the VCS name to the function
    method._vcs_handler = vcs
    # Store in a registry for later lookup
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    register_vcs_handler._registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to get a traversal of the hierarchy.  If the object does not
    # provide a `traverse` method, fall back to treating the root itself as
    # a single object.
    if hasattr(self, "_root") and hasattr(self._root, "traverse"):
        iterator = self._root.traverse()
    else:
        iterator = [self] if hasattr(self, "is_object") else []

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Object-level validation
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    obj.validate()
                elif hasattr(obj, "is_valid"):
                    if not getattr(obj, "is_valid"):
                        is_valid = False
                # If no validation method/property is available, assume valid
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Validation failed for {obj!r}: {exc}")

        # Digest check
        if check_digests:
            try:
                if hasattr(obj, "compute_digest") and hasattr(obj, "digest"):
                    computed = obj.compute_digest()
                    if computed != obj.digest:
                        is_valid = False
                        if show_warnings:
                            print(f"[WARN] Digest mismatch for {obj!r}: expected {obj.digest!r}, got {computed!r}")
                # If no digest methods/properties, skip check
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

