def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids:
        # Normalize bug_ids to a list of ints
        if isinstance(bug_ids, str):
            bug_ids = [int(x) for x in bug_ids.split(',') if x]
        elif not isinstance(bug_ids, list):
            bug_ids = [bug_ids]
        # Merge with existing 'ids' if present
        if 'ids' in params:
            existing = params['ids']
            if isinstance(existing, str):
                existing = [int(x) for x in existing.split(',') if x]
            elif not isinstance(existing, list):
                existing = [existing]
            # Combine and deduplicate while preserving order
            combined = []
            for id_ in existing + bug_ids:
                if id_ not in combined:
                    combined.append(id_)
            params['ids'] = combined
        else:
            params['ids'] = bug_ids
    return params

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values for duplicate keys.
    """
    def merge_mapping_nodes(existing_map, new_map):
        # Merge two MappingNode values (their .value lists)
        existing_items = existing_map.value
        new_items = new_map.value

        # Map existing keys to their index in the list
        key_to_index = {item[0].value: idx for idx, item in enumerate(existing_items)}

        for new_key_node, new_val_node in new_items:
            key = new_key_node.value
            if key in key_to_index:
                idx = key_to_index[key]
                existing_key_node, existing_val_node = existing_items[idx]
                # If both values are MappingNode, merge recursively
                if isinstance(existing_val_node, ruamel.yaml.nodes.MappingNode) and isinstance(new_val_node, ruamel.yaml.nodes.MappingNode):
                    merged_val = merge_mapping_nodes(existing_val_node, new_val_node)
                    existing_items[idx] = (existing_key_node, merged_val)
                else:
                    # Last wins
                    existing_items[idx] = (existing_key_node, new_val_node)
            else:
                # Append new key/value
                existing_items.append((new_key_node, new_val_node))
                key_to_index[key] = len(existing_items) - 1
        return existing_map

    result = []
    key_to_index = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_to_index:
            idx = key_to_index[key]
            existing_key_node, existing_val_node = result[idx]
            if isinstance(existing_val_node, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = merge_mapping_nodes(existing_val_node, val_node)
                result[idx] = (existing_key_node, merged_val)
            else:
                # Last wins
                result[idx] = (existing_key_node, val_node)
        else:
            result.append((key_node, val_node))
            key_to_index[key] = len(result) - 1
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    from collections import OrderedDict
    def merge_mapping_nodes(node1, node2):
        # node1 and node2 are MappingNode instances
        merged = OrderedDict()
        # add entries from node1
        for k_node, v_node in node1.value:
            merged[k_node.value] = (k_node, v_node)
        # merge entries from node2
        for k_node, v_node in node2.value:
            key = k_node.value
            if key in merged:
                _, existing_v = merged[key]
                # if both values are MappingNode, merge recursively
                if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v_node, ruamel.yaml.nodes.MappingNode):
                    merged[key] = (k_node, merge_mapping_nodes(existing_v, v_node))
                else:
                    merged[key] = (k_node, v_node)
            else:
                merged[key] = (k_node, v_node)
        # build new MappingNode
        new_value = list(merged.values())
        return ruamel.yaml.nodes.MappingNode(tag=node1.tag, value=new_value)

    result = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key in result:
            _, existing_value = result[key]
            if isinstance(existing_value, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_value = merge_mapping_nodes(existing_value, value_node)
                result[key] = (key_node, merged_value)
            else:
                result[key] = (key_node, value_node)
        else:
            result[key] = (key_node, value_node)
    return list(result.values())

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings for this action
        flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Helper to count occurrences of items in a list
    def _count_list(lst):
        counts = {}
        for item in lst:
            counts[item] = counts.get(item, 0) + 1
        return counts

    # Helper to subtract two count dictionaries: a - b
    def _subtract_counts(a, b):
        result = {}
        for key, val in a.items():
            rem = val - b.get(key, 0)
            if rem > 0:
                result[key] = rem
        return result

    # Helper to expand a count dictionary back into a list
    def _expand_counts(counts):
        lst = []
        for key, val in counts.items():
            lst.extend([key] * val)
        return lst

    # If there are no subparsers, simply return empty dict and the original arguments
    if not subparsers:
        return {}, list(unparsed_arguments)

    # Count all unparsed arguments
    all_counts = _count_list(unparsed_arguments)

    parsed_namespaces = {}
    # Keep track of all arguments claimed by any subparser
    claimed_counts = {}

    for name, parser in subparsers.items():
        # Parse known arguments for this subparser
        namespace, remaining = parser.parse_known_args(unparsed_arguments)
        parsed_namespaces[name] = namespace

        # Count remaining arguments for this subparser
        remaining_counts = _count_list(remaining)

        # Arguments claimed by this subparser = all_counts - remaining_counts
        claimed_this = _subtract_counts(all_counts, remaining_counts)

        # Merge into the global claimed_counts
        for key, val in claimed_this.items():
            claimed_counts[key] = claimed_counts.get(key, 0) + val

    # Remaining arguments not claimed by any subparser
    remaining_counts = _subtract_counts(all_counts, claimed_counts)
    remaining_args = _expand_counts(remaining_counts)

    return parsed_namespaces, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    s = size.strip()
    if not s:
        raise ValueError("Size string is empty")

    # Find the numeric part
    i = 0
    while i < len(s) and (s[i].isdigit() or s[i] in ".-+eE"):
        i += 1
    num_part = s[:i]
    suffix = s[i:].strip().lower()

    if not num_part:
        raise ValueError(f"Invalid size format: {size!r}")

    try:
        num = float(num_part)
    except ValueError:
        raise ValueError(f"Invalid numeric value: {num_part!r}")

    # Normalize suffix (allow optional trailing 'b')
    if suffix.startswith("b"):
        suffix = suffix[1:]

    factor = 1
    if suffix:
        if suffix[0] == "k":
            factor = 1000
        elif suffix[0] == "m":
            factor = 1000**2
        elif suffix[0] == "g":
            factor = 1000**3
        elif suffix[0] == "t":
            factor = 1000**4
        elif suffix[0] == "p":
            factor = 1000**5
        elif suffix[0] == "e":
            factor = 1000**6
        else:
            raise ValueError(f"Unknown size suffix: {suffix!r}")

    return int(round(num * factor))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    # Replace {key} placeholders
    def _repl_braces(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))
    url = re.sub(r'\{(\w+)\}', _repl_braces, url)
    # Replace :key placeholders
    url = re.sub(r':(\w+)', lambda m: str(url_args.get(m.group(1), m.group(0))), url)
    return url

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings (e.g., ['-h', '--help'])
        flags.extend(action.option_strings)
    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Negative numbers are not supported")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two characters")
    # Handle zero explicitly
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    # Apply padding if requested
    if padding is not None:
        if padding < 0:
            raise ValueError("Padding must be non-negative")
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result
    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            for key, val in list(obj.items()):
                if key == register_value:
                    obj[key] = register_number
                else:
                    _replace_in_obj(val)
        elif isinstance(obj, list):
            for item in obj:
                _replace_in_obj(item)

    _replace_in_obj(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if value is None:
        return None
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subs = set(cls.__subclasses__())
    for sub in list(subs):
        subs.update(subclasses(sub))
    return subs

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols")
    value = 0
    for ch in string:
        try:
            digit = alphabet.index(ch)
        except ValueError:
            raise ValueError(f"Character '{ch}' not in alphabet")
        value = value * base + digit
    return value

