def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        raise ValueError("Empty frequency string")
    if freq.lower() == "always":
        return None

    import re
    match = re.fullmatch(r'\s*(\d+)\s*([a-zA-Z]+)\s*', freq)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    number_str, unit = match.groups()
    number = int(number_str)

    unit = unit.lower()
    # Normalize unit to singular form
    if unit.endswith('s') and len(unit) > 1:
        unit = unit[:-1]

    unit_map = {
        'day': 'days',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
        'week': 'weeks',
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: {unit!r}")

    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string checks for common localhost identifiers
    if host.lower() == 'localhost':
        return True
    if host in ('127.0.0.1', '::1'):
        return True
    try:
        # Resolve the host to its IP addresses
        addrinfo = socket.getaddrinfo(host, None)
        ips = {ai[4][0] for ai in addrinfo}
    except socket.gaierror:
        return False
    # Gather local IP addresses
    local_ips = {'127.0.0.1', '::1'}
    try:
        hostname = socket.gethostname()
        local_ips.update(socket.gethostbyname_ex(hostname)[2])
    except Exception:
        pass
    # If any resolved IP matches a local IP, consider it local
    return bool(ips & local_ips)

