def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, os, re, logging
    config_map = {}
    error_records = []
    logger_name = 'config_loader'
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                data = json.load(f)
            if overrides:
                # shallow merge overrides into data
                if isinstance(data, dict):
                    data.update(overrides)
            if resolve_env:
                # recursively replace ${VAR} in string values
                def resolve(value):
                    if isinstance(value, str):
                        pattern = re.compile(r'\$\{([^}]+)\}')
                        def repl(match):
                            return os.getenv(match.group(1), match.group(0))
                        return pattern.sub(repl, value)
                    elif isinstance(value, dict):
                        return {k: resolve(v) for k, v in value.items()}
                    elif isinstance(value, list):
                        return [resolve(v) for v in value]
                    else:
                        return value
                data = resolve(data)
            config_map[filename] = data
        except Exception as exc:
            # create a LogRecord for the error
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to load configuration from {filename}: {exc}",
                args=(),
                exc_info=exc
            )
            error_records.append(record)
    return config_map, error_records

