def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    # If args is a mapping of argument names to values
    if isinstance(args, dict):
        for name, value in args.items():
            if value is None or (isinstance(value, str) and value == ''):
                silent.append(name)
    # If args is a sequence of (name, value) pairs
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                name, value = item
                if value is None or (isinstance(value, str) and value == ''):
                    silent.append(name)
    # If args is a simple list of names, return it as is
    elif isinstance(args, (set, frozenset)):
        silent = list(args)
    else:
        # Unsupported type: return empty list
        silent = []
    return silent

