    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        # Ensure args is a mapping for eval or callable usage
        if not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}
        for opt in options_spec:
            cond = opt.get("required_when")
            if cond:
                # If the condition is a callable, call it with args
                if callable(cond):
                    try:
                        if cond(args):
                            required.append(opt["name"])
                    except Exception:
                        # ignore errors in condition evaluation
                        pass
                else:
                    # Treat the condition as a string expression
                    try:
                        if eval(cond, {}, args):
                            required.append(opt["name"])
                    except Exception:
                        # ignore errors in eval
                        pass
        return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Ensure args is a mapping of argument names to values
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of argument names to values")

        # Determine the source of maximum lengths
        # Prefer an attribute named `max_lengths` if present; otherwise, look for
        # a method `get_max_length(arg_name)` that returns the limit.
        max_lengths = getattr(self, "max_lengths", None)
        get_max_length = getattr(self, "get_max_length", None)

        for name, value in args.items():
            # Skip values that don't have a length (e.g., None, int, etc.)
            try:
                length = len(value)
            except Exception:
                continue

            # Resolve the maximum allowed length for this argument
            if max_lengths is not None:
                max_len = max_lengths.get(name)
            elif get_max_length is not None:
                max_len = get_max_length(name)
            else:
                max_len = None

            # If a maximum length is defined and the value exceeds it, raise an error
            if max_len is not None and length > max_len:
                raise ValueError(
                    f"Argument '{name}' exceeds maximum length of {max_len} "
                    f"(actual length: {length})"
                )

        # If all checks pass, return True
        return True

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Determine the mapping of argument names to values
        if isinstance(args, dict):
            arg_values = args
        else:
            # Assume argparse.Namespace or similar
            arg_values = vars(args)

        # Iterate over each argument that has defined choices
        for name, value in arg_values.items():
            if not hasattr(self, "_choices") or name not in self._choices:
                continue

            allowed = self._choices[name]
            # If the value is a collection, validate each element
            if isinstance(value, (list, tuple, set)):
                for item in value:
                    if item not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{name}': {item!r} "
                            f"not in allowed choices {allowed!r}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value!r} "
                        f"not in allowed choices {allowed!r}"
                    )
        return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure min and max attributes are defined
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Both 'min' and 'max' attributes must be defined on the instance.")
    min_val = self.min
    max_val = self.max

    # Support both dicts and iterable collections
    if isinstance(args, dict):
        iterable = args.items()
        for key, value in iterable:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument '{key}' with value {value} is out of bounds [{min_val}, {max_val}]."
                )
    else:
        for idx, value in enumerate(args):
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument at index {idx} with value {value} is out of bounds [{min_val}, {max_val}]."
                )
    return True

