@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if not extra_vars:
        return vars_dict
    for var in extra_vars:
        if not isinstance(var, str) or '=' not in var:
            continue
        key, value = var.split('=', 1)
        if ',' in value:
            value = value.split(',')
        vars_dict[key] = value
    return vars_dict

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    cmd = ['ansible-playbook'] + cli_args
    if vars_dict:
        extra = ' '.join(f'{k}={v}' for k, v in vars_dict.items())
        cmd += ['--extra-vars', extra]
    subprocess = __import__('subprocess')
    result = subprocess.run(cmd, cwd=getattr(ir_workspace, 'path', None), capture_output=True, text=True)
    return {
        'stdout': result.stdout,
        'stderr': result.stderr,
        'returncode': result.returncode
    }

