def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    spec = None
    # Try YAML first
    yaml_path = os.path.join(plugin_dir, 'plugin.yaml')
    json_path = os.path.join(plugin_dir, 'plugin.json')
    if yaml and os.path.isfile(yaml_path):
        try:
            with open(yaml_path, 'r', encoding='utf-8') as f:
                spec = yaml.safe_load(f)
        except Exception:
            spec = None
    if spec is None and os.path.isfile(json_path):
        try:
            with open(json_path, 'r', encoding='utf-8') as f:
                spec = json.load(f)
        except Exception:
            spec = None
    if not spec:
        return {}
    if not isinstance(spec, dict):
        return {}
    return _flatten(spec)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("Root cannot be empty.")
    # Normalize root: remove trailing slashes unless root is just a slash
    if root not in ('/', '\\'):
        root = root.rstrip('/\\')
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    stripped = path[len(root):]
    # Remove leading separator if present
    if stripped.startswith('/') or stripped.startswith('\\'):
        stripped = stripped[1:]
    return stripped
